#!/usr/bin/env python3
"""Summarise staging application logs as JSON.

Usage: parse_logs.py <log-directory>

Reads every file in the directory, aggregates per day (from the UTC
timestamp) and per service, and prints a summary as described in
docs/output.md. Lines that do not match the documented format
(docs/log_format.md) are counted as "unparsed" and never crash the
script. Standard library only.
"""

import json
import math
import os
import re
import sys
from datetime import datetime

LEVELS = ("INFO", "WARN", "ERROR")

HEADER_RE = re.compile(r"^(\S+)\s+(INFO|WARN|ERROR)\s+(.*)$")
MSG_RE = re.compile(r'\bmsg="[^"]*"')
KV_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)=(\S*)$")
TIMESTAMP_FORMAT = "%Y-%m-%dT%H:%M:%SZ"

DEGRADED_ERROR_NUM = 10        # degraded if errors * 10 > lines (>10%)
DEGRADED_P95_MS = 2000         # degraded if p95 exceeds this
CRITICAL_DAYS = 2              # critical if degraded on >= this many days


def parse_line(line):
    """Return (date, level, svc, latency_ms) or None if malformed."""
    match = HEADER_RE.match(line)
    if not match:
        return None
    timestamp, level, rest = match.groups()

    try:
        day = datetime.strptime(timestamp, TIMESTAMP_FORMAT).date().isoformat()
    except ValueError:
        return None

    msg_match = MSG_RE.search(rest)
    if not msg_match:
        return None
    fields = rest[: msg_match.start()] + " " + rest[msg_match.end():]

    values = {}
    for token in fields.split():
        kv = KV_RE.match(token)
        if not kv:
            return None
        values[kv.group(1)] = kv.group(2)

    svc = values.get("svc")
    latency = values.get("latency_ms")
    if not svc or "req" not in values or latency is None:
        return None
    try:
        latency_ms = int(latency)
    except ValueError:
        return None
    if latency_ms < 0:
        return None

    return day, level, svc, latency_ms


def p95_nearest_rank(latencies):
    ordered = sorted(latencies)
    rank = math.ceil(95 * len(ordered) / 100)
    return ordered[rank - 1]


def summarize(log_dir):
    days = {}
    unparsed = 0

    for name in sorted(os.listdir(log_dir)):
        path = os.path.join(log_dir, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as handle:
                for raw in handle:
                    parsed = parse_line(raw.rstrip("\r\n"))
                    if parsed is None:
                        unparsed += 1
                        continue
                    day, level, svc, latency_ms = parsed
                    bucket = days.setdefault(day, {}).setdefault(
                        svc, {"lines": 0, "errors": 0, "latencies": []}
                    )
                    bucket["lines"] += 1
                    if level == "ERROR":
                        bucket["errors"] += 1
                    bucket["latencies"].append(latency_ms)
        except OSError:
            continue

    degraded_days = {}
    days_out = {}
    for day in sorted(days):
        services_out = {}
        for svc in sorted(days[day]):
            bucket = days[day][svc]
            lines = bucket["lines"]
            p95 = p95_nearest_rank(bucket["latencies"])
            degraded = (
                bucket["errors"] * DEGRADED_ERROR_NUM > lines
                or p95 > DEGRADED_P95_MS
            )
            if degraded:
                degraded_days[svc] = degraded_days.get(svc, 0) + 1
            services_out[svc] = {
                "lines": lines,
                "error_rate": round(bucket["errors"] / lines, 3),
                "p95_ms": p95,
                "degraded": degraded,
            }
        days_out[day] = services_out

    critical = sorted(
        svc for svc, count in degraded_days.items() if count >= CRITICAL_DAYS
    )
    return {"days": days_out, "critical": critical, "unparsed": unparsed}


def main(argv):
    if len(argv) != 2 or not os.path.isdir(argv[1]):
        print("usage: parse_logs.py <log-directory>", file=sys.stderr)
        return 2
    print(json.dumps(summarize(argv[1])))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
